INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1272211, 162979, 31214, '<td valign="top">Nice shot....as if he''s looking through you!  I think it is a great shot but could even be better if the background were more consistent in color (not the split in the middle).</td>', 'Nice shot....as if he''s looking through you!  I think it is a great shot but could even be better if the background were more consistent in color (not the split in the middle).', '2005-04-05 11:04:52.000000', NULL, 1),
(1272212, 163109, 31443, '<td valign="top">Very sweet...</td>', 'Very sweet...', '2005-04-05 11:04:54.000000', NULL, 1),
(1272220, 162857, 31443, '<td valign="top">Indeed! Would love to hear more about this one.. a Llama?</td>', 'Indeed! Would love to hear more about this one.. a Llama?', '2005-04-05 11:09:50.000000', NULL, 1),
(1272229, 162766, 31443, '<td valign="top">Good looking dogs here....</td>', 'Good looking dogs here....', '2005-04-05 11:15:14.000000', NULL, 1),
